import{_ as n,C as o,o as s,c as a,j as r,a as i,E as d,a2 as h}from"./chunks/framework.sc8Z_ZE3.js";const b=JSON.parse('{"title":"Server runners","description":"","frontmatter":{},"headers":[],"relativePath":"install/runners.md","filePath":"install/runners.md"}'),l={name:"install/runners.md"};function c(u,e,p,m,g,f){const t=o("Badge");return s(),a("div",null,[e[0]||(e[0]=r("h1",{id:"server-runners",tabindex:"-1"},[i("Server runners "),r("a",{class:"header-anchor",href:"#server-runners","aria-label":'Permalink to "Server runners"'},"​")],-1)),d(t,{type:"built",text:"Built"}),e[1]||(e[1]=h(' Server runners are a pool of sandboxed containers your installation runs itself. A chat turn, a scheduled task or a workflow step that does not run on a person&#39;s own device runs on a server runner, as Codex, under the same launcher, driver and hooks as on a device. The platform sees each runner as a device of the technical account <code>octryx-runner</code>, serving every Workspace that allows server runners.<h2 id="what-a-runner-is" tabindex="-1">What a runner is <a class="header-anchor" href="#what-a-runner-is" aria-label="Permalink to &quot;What a runner is&quot;">​</a></h2><ul><li><strong>One image:</strong> <code>octryx-runner</code>, with Codex pinned, the launcher, Python, git, ripgrep, ast-grep, ruff and a headless Chromium with Playwright. No language toolchains: add yours in <a href="/docs/install/runner-image">your own image</a>.</li><li><strong>Two accounts:</strong> the launcher (uid 10001) holds the device credential and writes each session&#39;s Codex configuration and hook chain. Codex and everything it runs (commands, tools, hooks) run as the agent&#39;s account (uid 10002), with no capabilities.</li><li><strong>Read-only where it matters:</strong> the session&#39;s configuration, its hook chain, the launcher and Codex itself are read-only for the agent, so even a session with full access cannot switch its hooks off. The launcher checks the chain between rounds.</li><li><strong>A token broker:</strong> the agent&#39;s processes get the model-gateway and MCP tokens they need from a socket of the launcher, never the device credential or the join secret.</li><li><strong>Governed only:</strong> a runner runs models through the platform&#39;s gateway, never a person&#39;s seat. A phase that needs a seat pauses for a <a href="/docs/work/seat-takeover">seat takeover</a>.</li></ul><p>Behind the container boundary Codex runs without its own sandbox. &quot;Ask before changes&quot; in the chat becomes Codex&#39;s approval policy <code>untrusted</code>: every command not known to be read-only is asked in the chat.</p><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><p>A runner reaches only the <strong>runner gateway</strong>, a small nginx that forwards to the platform&#39;s port. No database, no object store, no LiteLLM, no internet, and no git host: <code>git push</code> has nowhere to go.</p><p>A gateway call from a runner acts for the person whose turn it runs, and only while that turn is active: their Workspace membership, budget and usage, never a standing access of the runner account.</p><h2 id="one-person-at-a-time" tabindex="-1">One person at a time <a class="header-anchor" href="#one-person-at-a-time" aria-label="Permalink to &quot;One person at a time&quot;">​</a></h2><p>All sessions of a runner share the agent&#39;s account and its disk. So a runner serves <strong>one person in one Workspace at a time</strong>: the platform offers it nobody else&#39;s turn while one is active. Before the first turn of another person or Workspace, the launcher empties the working folders, the agent&#39;s home and the Codex and session state.</p><p>A thread that comes back to an emptied runner gets an empty folder; the launcher restores its Codex thread from the <a href="/docs/work/session-pool#session-files">session files</a> the platform keeps. The platform prefers the runner that already holds the thread when it is free, else the least busy one.</p><h2 id="repositories-on-a-runner" tabindex="-1">Repositories on a runner <a class="header-anchor" href="#repositories-on-a-runner" aria-label="Permalink to &quot;Repositories on a runner&quot;">​</a></h2><p>A runner holds no credential of the Workspace&#39;s Git connection. It reads the run&#39;s branch from the platform:</p><ol><li>It asks for a run-bound token, valid 10 minutes and checked again on every request: the turn must still be active, the person still a member, and the session and the run still bound together.</li><li>It fetches over read-only git from the run&#39;s working copy on the platform. Only the run&#39;s branch is visible. The token is never written to a URL, the command line or <code>.git/config</code>, and the agent&#39;s account never sees it.</li></ol><p>Nothing is pushed from a runner. The change goes to the platform as a patch; the platform pushes the reviewed change with its connection and opens the pull request. See <a href="/docs/work/git">Git repositories and pull requests</a>.</p><h2 id="when-every-runner-is-busy" tabindex="-1">When every runner is busy <a class="header-anchor" href="#when-every-runner-is-busy" aria-label="Permalink to &quot;When every runner is busy&quot;">​</a></h2><p>A chat message is kept and its turn waits as <strong>Waiting for a server runner</strong> until one is free, first come, first served. <strong>Stop</strong> cancels the wait. Without any server runner set up, the message is refused as <code>needs_configuration</code> (<code>runner_pool_not_set_up</code>).</p><h2 id="docker-compose" tabindex="-1">Docker Compose <a class="header-anchor" href="#docker-compose" aria-label="Permalink to &quot;Docker Compose&quot;">​</a></h2><p><code>docker compose up -d</code> starts one runner next to the platform (service <code>runner</code>). More with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scale</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> runner=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span></code></pre></div><p>Nothing else is needed: the first start writes a join secret into the <code>runner_join</code> volume, which only the platform and the runners mount, and each runner enrolls with it. A runner keeps its device credential in memory, so <strong>a restarted container enrolls as a new device</strong>; the old one stays offline in <strong>Admin › Devices</strong> until you remove it there.</p><p>The runner container has a memory limit of 4 GB.</p><h2 id="kubernetes" tabindex="-1">Kubernetes <a class="header-anchor" href="#kubernetes" aria-label="Permalink to &quot;Kubernetes&quot;">​</a></h2><p>The chart&#39;s runners are off by default.</p><table tabindex="0"><thead><tr><th>Value</th><th>What it does</th></tr></thead><tbody><tr><td><code>runners.enabled</code></td><td><code>true</code> runs the runners and the runner gateway</td></tr><tr><td><code>runners.replicas</code></td><td>how many runner pods (default 1)</td></tr><tr><td><code>runners.runtimeClassName</code></td><td>the RuntimeClass of the runner pods, for example gVisor; empty: the cluster&#39;s default</td></tr><tr><td><code>runners.storage</code></td><td>sizes of the runner&#39;s <code>tmp</code>, <code>workspace</code> and <code>state</code> (default 2Gi, 4Gi, 1Gi)</td></tr><tr><td><code>runners.networkPolicy.enabled</code></td><td>default <code>true</code>: a runner&#39;s egress is the runner gateway and the cluster DNS, and nothing reaches a runner (<code>runners.networkPolicy.dns</code> says where DNS runs)</td></tr><tr><td><code>resources.runner</code>, <code>resources.runnerGateway</code></td><td>requests and limits (runner default: 500m / 1Gi, limit 2 CPU / 4Gi)</td></tr><tr><td><code>images.runner.repository</code>, <code>tag</code>, <code>digest</code></td><td>your runner image</td></tr></tbody></table><p>Also:</p><ul><li>Build and push the runner image: <code>docker build -f docker/runner/Dockerfile -t &lt;registry&gt;/octryx-runner:&lt;tag&gt; .</code>, then set <code>images.runner.repository</code> and <code>tag</code>.</li><li>Add <code>RUNNER_JOIN_SECRET</code> (any long random value) to the existing Secret. The platform reads it; each runner pod gets only that key, as a file.</li><li>Your CNI must enforce NetworkPolicy. Check that it does.</li><li>The runner container starts as root with only the capabilities CHOWN, FOWNER, FSETID, SETUID and SETGID, used to hand its writable places to the launcher and the agent&#39;s account. The namespace needs the Pod Security level <code>baseline</code>, not <code>restricted</code>.</li><li>A new pod enrolls as a new device.</li></ul><h2 id="container-runtime-gvisor" tabindex="-1">Container runtime: gVisor <a class="header-anchor" href="#container-runtime-gvisor" aria-label="Permalink to &quot;Container runtime: gVisor&quot;">​</a></h2><p>Codex runs code with a shell, so the hardened option is gVisor (<code>runsc</code>), a user-space kernel between the session and the host. The runtime is configured, never guessed:</p><ul><li><strong>Compose:</strong> <code>RUNNER_RUNTIME=runsc</code> in <code>.env</code>. Docker then refuses to start a runner on a host without that runtime.</li><li><strong>Helm:</strong> <code>runners.runtimeClassName</code>, for example <code>gvisor</code>. Kubernetes starts no runner pod whose RuntimeClass does not exist (<code>kubectl get runtimeclass</code>).</li><li>In both, the platform admits only runners that report that runtime when they enroll (<code>runner_runtime_mismatch</code>). With no runner admitted, a turn for the pool answers <code>needs_configuration</code> (<code>runner_pool_unavailable</code>). Nothing falls back to the default runtime.</li></ul><p>Installing gVisor is the host&#39;s or the cluster&#39;s part: see the <a href="https://gvisor.dev/docs/user_guide/install/" target="_blank" rel="noreferrer">gVisor installation guide</a>.</p><div class="warning custom-block"><p class="custom-block-title">Not run end to end yet</p><p>gVisor is configured and enforced as above, but a chat turn and a workflow run on gVisor itself have not been run end to end yet.</p></div><h2 id="switch-runners-off-for-a-workspace" tabindex="-1">Switch runners off for a Workspace <a class="header-anchor" href="#switch-runners-off-for-a-workspace" aria-label="Permalink to &quot;Switch runners off for a Workspace&quot;">​</a></h2><p>A Workspace forbids server runners with <code>server_runners: &quot;forbidden&quot;</code> in its configuration. Then neither a chat turn nor a workflow run of that Workspace lands on a runner.</p><h2 id="a-browser-in-the-session" tabindex="-1">A browser in the session <a class="header-anchor" href="#a-browser-in-the-session" aria-label="Permalink to &quot;A browser in the session&quot;">​</a></h2><p>A run phase that asks for a browser gets the same Playwright MCP server as on a device, with Chromium for this session only: headless, its own profile, loopback pages only. A runner has no internet, so the image carries both at pinned versions. The session starts its app on <code>127.0.0.1</code>, opens it and sees the screenshots.</p><h2 id="size" tabindex="-1">Size <a class="header-anchor" href="#size" aria-label="Permalink to &quot;Size&quot;">​</a></h2><p>The image is about 5 GB: Python&#39;s Playwright and the Playwright MCP server each bring their own Chromium.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>gVisor is not run end to end yet (see above).</li><li>A restarted runner enrolls as a new device; remove the old one in <strong>Admin › Devices</strong>.</li><li>A runner serves one person in one Workspace at a time; more parallel work needs more runners.</li></ul><p>See also <a href="/docs/start/known-limitations">Known limitations</a>.</p>',42))])}const w=n(l,[["render",c]]);export{b as __pageData,w as default};
